const CONDITIONAL_REFERENCES = {
    realistic:
        "# 真人表演与对白\n\n附加参考：真人表演与对白。\n\n只在真人、角色对白、情感冲突、访谈、体育或综艺镜头中加载。\n\n- 先确定角色在本镜的目标、阻力和策略，再描述可观察行为；不要把“愤怒、害怕、感动”等情绪词当作完整表演指令。\n- 对白写清说话人、目标语言、短句、语气、停顿和重音；听者必须在接收到信息后才出现反应。\n- 情绪必须落到眉眼、嘴角、下颌、视线、呼吸、手部、重心、人与人距离或道具操作；每段至少保留一个可检查的变化。\n- 动作按准备、受力或接触、结果、恢复的因果顺序描述。人物必须有可见支撑面、合理接触点和真实可达的动作路径。\n- 只有需要表演变化时才增加镜头或时间段；不要用密集切镜掩盖缺少动机的表情变化。",
    multiCharacter:
        "# 多人物空间调度\n\n附加参考：多人物空间调度。\n\n只在两人及以上、对话、餐桌、车内、会议或群像任务中加载。\n\n- 用同一场景前进方向或镜头轴线描述人物左右、前后、朝向、视线和距离；不能在不同段落切换参照系。\n- 为每位出镜人物写明站立/坐姿支撑面、手部接触对象、道具归属、发言顺序和可见反应。\n- 封闭空间优先使用已有座位、长凳、床沿、桌面、通道、门窗和隔断；中央通道保持通行，未声明人物不入画。\n- 镜头反打、移动和转场保持屏幕方向、视线关系和 180 度轴线，除非 Prompt 明确设计了可观察的越轴动作。\n- 多人动作先减少并发事件，再让一个主体动作触发其他人的次级反应，避免同时出现无法辨认的手、道具和肢体归属。",
    example:
        "# 示例结构迁移\n\n附加参考：示例结构迁移。\n\n只在用户明确要求参考、模仿或复刻某个示例的结构时加载。\n\n- 先识别允许继承的维度：信息层级、时间粒度、镜头语法、节奏、动作因果、转场或声音组织。\n- 示例默认不转移人物身份、品牌、背景、台词、文字、水印、音乐、颜色或剧情；只有用户明确指定的维度才可继承。\n- 用当前用户的素材、角色、场景和时长重新构建 Prompt，不把示例描述直接拼接到新任务。\n- 复刻视频动作或镜头时，分别说明借用动作机制、摄影机节奏或构图中的哪一项，并写明不继承内容。",
    failure:
        "# 失败诊断\n\n附加参考：失败诊断。\n\n先按第一个失败层定位，不要一次重写全部提示词：\n\n1. 身份漂移：收紧唯一身份来源、服装、体型和道具归属。\n2. 参考串绑：拆分素材职责和作用范围，补充禁止继承项。\n3. 构图错误：固定景别、机位、屏幕方向和主体位置。\n4. 动作错误：补齐准备、接触/受力、结果和恢复的因果顺序。\n5. 物理错误：补足支撑面、接触点、距离、遮挡和空间通道。\n6. 时间错误：合并过密事件，使每段终点成为下一段起点。\n7. 音频错误：明确对白、环境声、音乐、静音和字幕之间的优先级。\n8. 连续性错误：只使用当前已验收的边界状态，不引用旧任务或未确认素材。\n\n诊断时先保留已经通过验收的身份、服装、资产、空间轴线、光向和声音；然后只改失败层的一项变量。示例结构、参考视频和角色素材出现冲突时，优先修正职责和作用范围，而不是追加更多泛化否定词。\n\n每次返修只改变一个已定位变量；保留通过验收的参考图、角色状态、空间轴线和声音规则。",
};
const REALISTIC_DIRECTION_RE = /真人|人物|角色|对话|台词|口型|情感|情绪|表演|情侣|访谈|综艺|体育|运动员/iu;
const MULTI_CHARACTER_RE = /多人|两人|双人|三人|四人|群像|对手|彼此|对话|会议|餐桌|车内/iu;
const EXAMPLE_STRUCTURE_RE = /参考(?:结构|示例|镜头)|参考\s*@?(?:图片|视频|音频)|模仿|复刻|参照/iu;
const FAILURE_DIAGNOSIS_RE = /失败|翻车|漂移|变形|模糊|错位|不一致|不符合|重试|修复/iu;

function conditionalReferences(prompt: string) {
    return [
        REALISTIC_DIRECTION_RE.test(prompt) ? CONDITIONAL_REFERENCES.realistic : "",
        MULTI_CHARACTER_RE.test(prompt) ? CONDITIONAL_REFERENCES.multiCharacter : "",
        EXAMPLE_STRUCTURE_RE.test(prompt) ? CONDITIONAL_REFERENCES.example : "",
        FAILURE_DIAGNOSIS_RE.test(prompt) ? CONDITIONAL_REFERENCES.failure : "",
    ].filter(Boolean);
}

export function resolveSeedance25VideoPromptRoute(input: Seedance25VideoPromptReferenceInput): Seedance25VideoPromptRoute {
    const prompt = input.prompt || "";
    if (/(?:智能|高级|局部)?编辑|替换|移除|删除|保留原片|change\s*\/\s*preserve/iu.test(prompt)) return "video-edit";
    if (/续写|延长|接着拍|接续|扩展|prepend|append/iu.test(prompt)) return "video-extension";
    if (/白模|clay(?:\s*renderer)?|blockout/iu.test(prompt)) return "clay-renderer";
    if (/无缝转场|两段视频|桥接(?:片段)?|seamless\s*transition/iu.test(prompt)) return "seamless-transition";
    if (/多宫格|分镜板|故事板|storyboard\s*grid/iu.test(prompt)) return "multi-grid-storyboard";
    if (/长视频|超长|long\s*video/iu.test(prompt) || (input.durationSeconds || 0) > 30) return "long-video";
    return input.durationSeconds === 30 ? "timestamp-30s" : "basic-multimodal";
}

export function resolveSeedance25VideoPromptReferences(input: Seedance25VideoPromptReferenceInput) {
    const route = resolveSeedance25VideoPromptRoute(input);
    return { route, instructions: [ROUTE_REFERENCES[route], ...conditionalReferences(input.prompt || "")].filter(Boolean).join("\n\n") };
}

export function inferSeedance25VideoDuration(prompt: string) {
    const values = Array.from(prompt.matchAll(/(?:^|[^\d])(\d{1,3})\s*(?:秒|s)(?!\w)/giu), (match) => Number(match[1])).filter((value) => Number.isFinite(value) && value > 0);
    return values.length ? values.at(-1) : undefined;
}

export function resolveSeedance25DirectorInstructions(input: Seedance25VideoPromptReferenceInput) {
    const reference = resolveSeedance25VideoPromptReferences(input);
    return { route: reference.route, instructions: SEEDANCE_25_DIRECTOR_SKILL.instructions + "\n\n" + reference.instructions };
}
